/**
 * Read-only lifecycle hook engine shared by Claude Code, Codex CLI, and
 * OpenCode. Every evaluator is a pure read of the project: it never writes
 * to `.fyi/`, never blocks, and returns an empty result when it has nothing
 * high-signal to say.
 *
 * Host paths/protocols live in hosts.mjs, config merging in hook-config.mjs,
 * prompt relevance in relevance.mjs. This module re-exports them so callers
 * (including OpenCode plugins generated by earlier versions) keep one entry.
 */
import { closeSync, openSync, readSync, fstatSync } from 'node:fs';
import { basename, dirname, isAbsolute, relative, resolve } from 'node:path';
import { hasLocalSkill, resolveCliForAgent, formatRuntimeCli, runtimeCommand } from './hosts.mjs';
import { isEligible, rankForPrompt, extractPromptTerms, shouldSkipPrompt } from './relevance.mjs';
import { indexStatus, isInitialized, readConfig, configIssues, snapshot, storeFingerprint, walkArtifacts } from './store.mjs';
import { isFile, oneLine, realpathSafe, toPosix } from './util.mjs';

export * from './hosts.mjs';
export {
  cliPathFromCommand,
  inspectIntegrations,
  installHooks,
  isFyiHandler,
  projectHasFyiHooks,
  skillVersionDrift,
  uninstallHooks,
} from './hook-config.mjs';
export { renderOpenCodePlugin } from './opencode-plugin.mjs';
export { extractPromptTerms, rankForPrompt, shouldSkipPrompt, tokenize } from './relevance.mjs';
export { storeFingerprint };

/** Bumped when evaluator signatures change; generated plugins feature-detect functions. */
export const ENGINE_API = 2;

const TRANSCRIPT_TAIL_BYTES = 512 * 1024;

function runtimeCli(root, host, cliPath) {
  return resolveCliForAgent(root, host === 'plain' ? 'claude' : host, cliPath);
}

/** Read-only SessionStart evaluation: concise store state + behavioral directives. */
export function evaluateSessionStart(root, options = {}) {
  const empty = (state) => ({ initialized: false, additionalContext: '', skipped: state });
  if (options.source === 'resume') return { ...empty('resume'), initialized: isInitialized(root) };

  const cliInfo = runtimeCli(root, options.host || 'claude', options.cliPath);
  const cli = formatRuntimeCli(root, cliInfo);
  const snap = snapshot(root);

  if (!snap.initialized) {
    // Stay silent in repos that never opted in (e.g. a user-wide plugin opened elsewhere).
    if (!hasLocalSkill(root)) return empty('not-opted-in');
    return {
      initialized: false,
      additionalContext: [
        '<fyi-context>',
        'Project memory (.fyi/) is not initialized yet. If this task produces reusable debugging recipes, ownership, or runbooks, run `init` first (skip for read-only tasks).',
        `CLI: \`${cli}\``,
        '</fyi-context>',
      ].join('\n'),
      state: { initialized: false, apps: [], counts: snap.counts },
    };
  }

  const { counts: summary, apps, issues, index, config } = snap;
  const typeParts = Object.entries(summary.byType).map(([type, count]) => `${count} ${type}`);
  const lines = [
    '<fyi-context>',
    `Project memory (.fyi/) is active: ${summary.unarchived} artifact${summary.unarchived === 1 ? '' : 's'}${
      typeParts.length ? ` (${typeParts.join(', ')})` : ''
    } · apps: ${apps.length ? apps.join(', ') : 'none'} · index: ${index}.`,
    `CLI: \`${cli}\``,
    'Rules:',
    '- Search before solving: for debugging, tracing, ownership, or "how does X work", run `find "<symptom>"` first.',
    '- Capture after solving: save reusable recipes when asked to remember/save/document; otherwise offer in one line (`new pattern "<title>"`).',
    '- Redact secrets and raw logs before writing. Never hand-edit generated INDEX.md or index.json.',
  ];
  if (!config) lines.push('Notice: .fyi/config.json is missing or unreadable; run `init` or `doctor`.');
  else if (issues.length) lines.push(`Notice: config warning (${issues[0]}); run \`doctor\`.`);
  if (index !== 'fresh') lines.push('Notice: .fyi/ index is stale; run `index` before relying on INDEX.md.');
  lines.push('</fyi-context>');

  return {
    initialized: true,
    additionalContext: lines.join('\n'),
    state: { initialized: true, apps, index, counts: summary },
  };
}

/** Read the tail of a host transcript to find artifact ids already injected this session. */
export function injectedIdsFromTranscript(transcriptPath, ids) {
  const found = new Set();
  if (!transcriptPath || !isAbsolute(String(transcriptPath)) || !isFile(transcriptPath) || !ids.length) {
    return found;
  }
  let fd;
  try {
    fd = openSync(transcriptPath, 'r');
    const size = fstatSync(fd).size;
    const length = Math.min(size, TRANSCRIPT_TAIL_BYTES);
    const buffer = Buffer.alloc(length);
    readSync(fd, buffer, 0, length, size - length);
    const text = buffer.toString('utf8');
    if (!text.includes('fyi-matches')) return found;
    for (const id of ids) if (text.includes(`(\`${id}\`)`)) found.add(id);
  } catch {
    // Unreadable transcript: fall back to injecting.
  } finally {
    if (fd !== undefined) closeSync(fd);
  }
  return found;
}

/** Read-only UserPromptSubmit evaluation: surface high-confidence .fyi/ matches only. */
export function evaluatePromptSubmit(root, prompt, options = {}) {
  const none = (terms = [], reason = '') => ({ matched: false, terms, matches: [], additionalContext: '', reason });
  const skip = shouldSkipPrompt(prompt);
  if (skip) return none([], skip);
  if (!isInitialized(root)) return none([], 'not-initialized');

  const terms = extractPromptTerms(prompt);
  if (!terms.length) return none([], 'no-terms');

  const artifacts = walkArtifacts(root).filter(isEligible);
  if (!artifacts.length) return none(terms, 'empty-store');

  let results = rankForPrompt(terms, artifacts, { limit: options.limit ?? 3 });
  if (results.length && options.transcriptPath) {
    const seen = injectedIdsFromTranscript(options.transcriptPath, results.map(({ artifact }) => artifact.id));
    results = results.filter(({ artifact }) => !seen.has(artifact.id));
  }
  if (!results.length) return none(terms, 'below-threshold');

  const cliInfo = runtimeCli(root, options.host || 'claude', options.cliPath);
  const lines = [
    '<fyi-matches>',
    'Relevant project memory in .fyi/ (check before re-deriving):',
    ...results.map(({ artifact }) => {
      const status = artifact.status && artifact.status !== 'active' ? ` [${artifact.status}]` : '';
      const desc = artifact.description ? ` — ${oneLine(artifact.description, 100)}` : '';
      return `- [${artifact.type}]${status} ${artifact.title} (\`${artifact.id}\`)${desc}`;
    }),
    `Read with: \`${runtimeCommand(root, cliInfo, 'show <id>')}\``,
    '</fyi-matches>',
  ];

  return {
    matched: true,
    terms,
    matches: results.map(({ artifact, score, matched }) => ({
      id: artifact.id,
      type: artifact.type,
      title: artifact.title,
      path: artifact.path,
      score,
      matched,
    })),
    additionalContext: lines.join('\n'),
  };
}

const PATCH_FILE_RE = /^\*\*\* (?:Add|Update|Delete) File: (.+)$|^\*\*\* Move to: (.+)$/gm;

/** Collect file paths an edit tool touched, across Claude, Codex, and OpenCode argument shapes. */
export function editedPaths(toolInput) {
  const out = [];
  const push = (value) => {
    if (typeof value === 'string' && value.trim() && !value.includes('\n')) out.push(value.trim());
  };
  const scanPatch = (text) => {
    if (typeof text !== 'string' || !text.includes('*** ')) return;
    for (const match of text.matchAll(PATCH_FILE_RE)) push(match[1] || match[2]);
  };
  if (typeof toolInput === 'string') {
    scanPatch(toolInput);
    return [...new Set(out)];
  }
  if (!toolInput || typeof toolInput !== 'object') return out;
  for (const key of ['file_path', 'filePath', 'path', 'notebook_path']) push(toolInput[key]);
  if (Array.isArray(toolInput.edits)) {
    for (const edit of toolInput.edits) {
      if (edit && typeof edit === 'object') push(edit.file_path || edit.filePath || edit.path);
    }
  }
  for (const key of ['patch', 'patchText', 'input', 'command']) {
    const value = toolInput[key];
    if (Array.isArray(value)) value.forEach(scanPatch);
    else scanPatch(value);
  }
  return [...new Set(out)];
}

function storeRelative(root, cwd, path) {
  const abs = resolve(cwd || root, path);
  const realAbs = resolve(realpathSafe(dirname(abs)), basename(abs));
  for (const storeAbs of [resolve(root, '.fyi'), realpathSafe(resolve(root, '.fyi'))]) {
    for (const candidate of [abs, realAbs]) {
      const rel = relative(storeAbs, candidate);
      if (rel && !rel.startsWith('..') && !isAbsolute(rel)) return toPosix(rel);
    }
  }
  return null;
}

/**
 * Read-only PostToolUse evaluation: when an edit touched `.fyi/`, tell the
 * agent (not the user) exactly what to run. Silent for every other edit and
 * whenever the index is already fresh.
 */
export function evaluatePostToolUse(root, payload = {}, options = {}) {
  const none = { additionalContext: '', touched: [] };
  if (!isInitialized(root)) return none;
  const touched = editedPaths(payload.tool_input)
    .map((path) => storeRelative(root, payload.cwd, path))
    .filter(Boolean);
  if (!touched.length) return none;

  const cliInfo = runtimeCli(root, options.host || 'claude', options.cliPath);
  const indexCmd = runtimeCommand(root, cliInfo, 'index');
  const doctorCmd = runtimeCommand(root, cliInfo, 'doctor');
  const generated = touched.filter((rel) => rel === 'INDEX.md' || rel === 'index.json');
  if (generated.length) {
    return {
      touched,
      additionalContext: [
        '<fyi-notice>',
        `${generated.join(' and ')} ${generated.length > 1 ? 'are' : 'is'} generated; hand edits are overwritten. Edit the artifact files instead, then run \`${indexCmd}\`.`,
        '</fyi-notice>',
      ].join('\n'),
    };
  }
  if (touched.includes('config.json')) {
    const cfg = readConfig(root);
    const issues = configIssues(cfg);
    if (!cfg || issues.length) {
      return {
        touched,
        additionalContext: [
          '<fyi-notice>',
          !cfg
            ? 'You edited .fyi/config.json, and it is now unreadable JSON.'
            : `You edited .fyi/config.json, which has a warning (${issues[0]}).`,
          `Run \`${doctorCmd}\` to verify.`,
          '</fyi-notice>',
        ].join('\n'),
      };
    }
  }
  if (indexStatus(root) === 'fresh') return { ...none, touched };
  return {
    touched,
    additionalContext: [
      '<fyi-notice>',
      `You edited ${touched.map((rel) => `.fyi/${rel}`).join(', ')}; the .fyi index is now stale.`,
      `Before finishing, run \`${indexCmd}\` and then \`${doctorCmd}\`.`,
      '</fyi-notice>',
    ].join('\n'),
  };
}

/** User-facing idle notice (OpenCode toast): stale index or broken config only. */
export function evaluateIdle(root) {
  if (!isInitialized(root)) return { systemMessage: '' };
  const config = readConfig(root);
  if (!config) return { systemMessage: 'fyi: .fyi/config.json is missing or unreadable; run `fyi doctor`.' };
  const issues = configIssues(config);
  if (issues.length) return { systemMessage: `fyi: .fyi/config.json needs attention (${issues[0]}).` };
  if (indexStatus(root) !== 'fresh') return { systemMessage: 'fyi: .fyi/ index is stale; run `fyi index`.' };
  return { systemMessage: '' };
}

/**
 * Legacy Stop evaluation kept for hook configs written by 1.0.0. Stop fires
 * every turn, so it only speaks when config.json is unreadable; stale-index
 * notices moved to PostToolUse where the agent can act on them.
 */
export function evaluateStop(root, payload = {}) {
  if (payload?.stop_hook_active) return { skipped: true, systemMessage: '' };
  if (!isInitialized(root)) return { skipped: false, systemMessage: '' };
  if (!readConfig(root)) {
    return { skipped: false, systemMessage: 'fyi: .fyi/config.json is missing or unreadable; run `fyi doctor`.' };
  }
  return { skipped: false, systemMessage: '' };
}
